command:
$ErrorActionPreference = 'Stop'

$branch = 'issue-476-architecture-b-calibration-benchmark'
$expectedHead = 'f0d156446c6916fc58c91501b9150794b28f761d'
$worktree = Join-Path $env:RUNNER_TEMP 'dcoir-issue-476-benchmark-validation'

git fetch origin $branch
if ($LASTEXITCODE -ne 0) { throw 'Failed to fetch issue #476 branch' }

git worktree add --detach $worktree "origin/$branch"
if ($LASTEXITCODE -ne 0) { throw 'Failed to create validation worktree' }

Push-Location $worktree
try {
    $actualHead = (git rev-parse HEAD).Trim()
    if ($actualHead -ne $expectedHead) {
        throw "Branch head mismatch: expected $expectedHead, got $actualHead"
    }

    python -m py_compile `
        .github/dcoir_review/scripts/dcoir_review_architecture_b_benchmark.py `
        .github/dcoir_review/scripts/dcoir_review_architecture_b_benchmark_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'Benchmark Python compile validation failed' }

    python -m json.tool `
        .github/dcoir_review/evaluation/architecture_b_benchmark_v1.json `
        > $null
    if ($LASTEXITCODE -ne 0) { throw 'Benchmark manifest JSON validation failed' }

    python .github/dcoir_review/scripts/openrouter_pr_review_pareto_context_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'Pareto context selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v41_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v41 selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v41_provenance_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v41 provenance selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v42_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v42 selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v43_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v43 selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v43_state_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v43 state selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v44_scope_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v44 scope selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v44_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v44 selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v45_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v45 selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v46_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'v46 selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_semantic_recall_corpus_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'Semantic recall corpus selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_precision_regression_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'Precision regression selftest failed' }

    python .github/dcoir_review/scripts/dcoir_review_architecture_b_benchmark_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'Architecture-B benchmark selftest failed' }

    $reportPath = Join-Path $env:DCOIR_DOWNLOADS_DIR 'architecture_b_benchmark_report.json'
    python .github/dcoir_review/scripts/dcoir_review_architecture_b_benchmark.py --output $reportPath
    if ($LASTEXITCODE -ne 0) { throw 'Architecture-B benchmark run failed' }

    bash .github/dcoir_review/scripts/validate-codex-local.sh `
        .github/dcoir_review/evaluation/architecture_b_benchmark_v1.json `
        .github/dcoir_review/openrouter-pr-review-pareto.yml `
        .github/dcoir_review/scripts/dcoir_review_architecture_b_benchmark.py `
        .github/dcoir_review/scripts/dcoir_review_architecture_b_benchmark_selftest.py
    if ($LASTEXITCODE -ne 0) { throw 'Changed-file validation failed' }

    $dirty = @(git status --porcelain)
    if ($dirty.Count -ne 0) {
        throw "Validation unexpectedly modified the branch worktree: $($dirty -join '; ')"
    }
}
finally {
    Pop-Location
}
